import{initHeader}from"/assets/js/header.min.js";const loadSliders=()=>{const e=[...document.querySelectorAll(".slider-wrapper")];e.length&&import("/assets/js/slider.min.js").then((t=>{e.forEach((e=>t.initSLider(e.id)))}))},loadTooltips=()=>{const e=[...document.querySelectorAll(".head .cell.bg")];e.length&&import("/assets/js/tooltip.min.js").then((t=>{t.initTooltips(e)}))},loadPagination=()=>{document.querySelector(".media-pagination")&&import("/assets/js/pagination.min.js").then((e=>{e.initPagination()}))},loadModal=()=>{const e=document.querySelector(".media-modal-wrapper");e&&import("/assets/js/modal.min.js").then((t=>{t.initModal(e)}))},loadVideo=()=>{document.querySelector(".media-gallery.video")&&import("/assets/js/video.min.js").then((e=>{e.initVideo()}))},loadContact=()=>{document.querySelector("section.form")&&import("/assets/js/contact.min.js").then((e=>{e.initContact()}))},loadHelper=()=>{initHeader(),loadSliders(),loadTooltips(),document.querySelector(".media-pagination")&&import("/assets/js/pagination.min.js").then((e=>{e.initPagination()})),loadModal(),document.querySelector(".media-gallery.video")&&import("/assets/js/video.min.js").then((e=>{e.initVideo()})),document.querySelector("section.form")&&import("/assets/js/contact.min.js").then((e=>{e.initContact()}))};window.addEventListener("load",loadHelper);